curl -sL "https://api.openalex.org/works/https://doi.org/10.1109/LRA.2024.3433200" | python3 -c "import sys,json; d=json.load(sys.stdin); print('title', d.get('title')); print('oa', d.get('open_access')); loc=d.get('primary_location') or {}; print('pdf', (loc.get('pdf_url'))); print('landing', loc.get('landing_page_url')); print('ids', d.get('ids')); oa_locs=d.get('locations') or [];
[print('loc', (x.get('source') or {}).get('display_name'), x.get('pdf_url'), x.get('is_oa')) for x in oa_locs]"

# Also try Unpaywall-style via openalex best_oa_location
curl -sL "https://api.openalex.org/works/https://doi.org/10.1109/LRA.2024.3433200" | python3 -c "import sys,json; d=json.load(sys.stdin); b=d.get('best_oa_location') or {}; print('best_oa', b)"

# Search openalex by title
curl -sL --get "https://api.openalex.org/works" --data-urlencode "search=LECES Low-Bandwidth Efficient Collaborative Exploration" --data-urlencode "per-page=3" | python3 -c "import sys,json; d=json.load(sys.stdin);
for r in d.get('results',[]):
 print('---'); print(r.get('title')); print(r.get('doi')); print((r.get('best_oa_location') or {}).get('pdf_url')); print(r.get('id'))"
